import{_ as r,a as o,b as t,c as s,d as a,e as i,f as u}from"./chunks/ajouter-un-produit.B4rfJJbd.js";import{_ as n,c as d,o as l,ae as p}from"./chunks/framework.DBgX5bsf.js";const P=JSON.parse('{"title":"Gestion des produits","description":"","frontmatter":{},"headers":[],"relativePath":"fr/docs/commerce/products.md","filePath":"fr/docs/commerce/products.md"}'),c={name:"fr/docs/commerce/products.md"};function m(h,e,g,v,f,b){return l(),d("div",null,e[0]||(e[0]=[p('<h1 id="gestion-des-produits" tabindex="-1">Gestion des produits <a class="header-anchor" href="#gestion-des-produits" aria-label="Permalink to &quot;Gestion des produits&quot;">​</a></h1><p>Les produits représentent des biens ou des services vendus dans votre magasin. Vous pouvez ajouter des produits simples ou des produits variables.</p><p>Avant de poursuivre, il est essentiel de comprendre la distinction entre les produits simples et les produits variables.</p><h2 id="produit-simple-vs-produit-variable" tabindex="-1">Produit simple vs Produit variable <a class="header-anchor" href="#produit-simple-vs-produit-variable" aria-label="Permalink to &quot;Produit simple vs Produit variable&quot;">​</a></h2><p>Un produit simple est un produit variable avec une seule variante. En réalité, les produits simples n&#39;existent pas en tant que tels.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>On vend toujours une variante d&#39;un produit. Un produit doit avoir au moins une variante, et si nécessaire, plusieurs.</p></div><p><strong>Exemple 1 :</strong> Pour la vente d&#39;un livre, créez un produit &quot;Livre&quot; et ajoutez une variante pour ce produit.<br><strong>Exemple 2 :</strong> Pour la vente d&#39;un t-shirt disponible en rouge et bleu, créez un produit &quot;T-shirt&quot; et ajoutez une variante pour chaque couleur.</p><h2 id="voir-la-liste-des-produits" tabindex="-1">Voir la liste des produits <a class="header-anchor" href="#voir-la-liste-des-produits" aria-label="Permalink to &quot;Voir la liste des produits&quot;">​</a></h2><p>Pour consulter la liste des produits, accédez à : <code>/admin/commerce/products</code><br><img src="'+r+'" alt="Liste des produits"></p><h2 id="modifier-un-produit" tabindex="-1">Modifier un produit <a class="header-anchor" href="#modifier-un-produit" aria-label="Permalink to &quot;Modifier un produit&quot;">​</a></h2><p>Pour modifier un produit, cliquez sur le bouton <code>Modifier</code> à côté du produit concerné.<br><img src="'+o+'" alt="Modifier un produit"></p><p>Pour modifier les informations du produit, vous serez redirigé vers la page de modification.<br><img src="'+t+'" alt="Modifier les informations sur un produit"><br> Cette image est numérotée de 1 à 10. Nous allons parcourir chaque point pour expliquer comment les modifier. Certains points concernent le produit, d&#39;autres la variante.</p><h3 id="champs-correspondant-au-produit" tabindex="-1">Champs correspondant au produit : <a class="header-anchor" href="#champs-correspondant-au-produit" aria-label="Permalink to &quot;Champs correspondant au produit :&quot;">​</a></h3><ul><li><strong>1 :</strong> Marque du produit. Correspond au champ <strong>Marques</strong> dans la page de modification.</li><li><strong>2 :</strong> Nom du produit. Correspond au champ <strong>Titre</strong>.</li><li><strong>4 :</strong> Description courte. Correspond au champ <strong>Description courte</strong>.</li><li><strong>7 :</strong> Descriptions supplémentaires. Correspond au champ <strong>Accordions</strong>.</li></ul><h3 id="champs-correspondant-a-la-variante" tabindex="-1">Champs correspondant à la variante : <a class="header-anchor" href="#champs-correspondant-a-la-variante" aria-label="Permalink to &quot;Champs correspondant à la variante :&quot;">​</a></h3><p>Accédez à la page de modification de la variante en cliquant sur le lien <strong>Variation</strong>. Vous verrez une ou plusieurs variantes. Cliquez sur <code>Modifier</code> à côté de la variante souhaitée.</p><ul><li><strong>3 :</strong> Prix de la variante. Correspond au champ <strong>Prix</strong>.</li><li><strong>5 :</strong> Attributs de variation (couleur, taille, etc.). Correspond aux champs <strong>Couleur</strong> et <strong>Taille</strong>.<br><img src="'+s+'" alt="Modifier les informations sur une variante"></li><li><strong>9 :</strong> Images du produit. Correspond au champ <strong>Galleries</strong>.</li></ul><h3 id="autres-champs" tabindex="-1">Autres champs : <a class="header-anchor" href="#autres-champs" aria-label="Permalink to &quot;Autres champs :&quot;">​</a></h3><ul><li><strong>6 :</strong> Bouton &quot;Ajouter au panier&quot;. Modifiable via : <code>/admin/config/system/commerceformatage</code>.<br><img src="'+a+'" alt="Modifier le bouton ajouter au panier"></li><li><strong>8 :</strong> Bloc de partage. Configurez les clés d&#39;API dans le thème (certains réseaux ne nécessitent pas de clé).</li><li><strong>10 :</strong> Bloc d&#39;avis. Modifiez l&#39;apparence ou supprimez-le en suivant les tutoriels sur les layouts.</li></ul><p>Nous avons terminé avec ces blocs d&#39;affichage.</p><h3 id="autres-caracteristiques" tabindex="-1">Autres caractéristiques <a class="header-anchor" href="#autres-caracteristiques" aria-label="Permalink to &quot;Autres caractéristiques&quot;">​</a></h3><p>Tout le contenu situé sous ce bloc est regroupé dans le champ <strong>Autres caractéristiques</strong>. Ces informations sont organisées en sections, chaque section contenant un ou plusieurs champs. Vous pouvez ajouter, modifier ou supprimer des sections.<br><img src="'+i+'" alt="Modifier les autres caractéristiques"></p><h2 id="ajouter-un-produit" tabindex="-1">Ajouter un produit <a class="header-anchor" href="#ajouter-un-produit" aria-label="Permalink to &quot;Ajouter un produit&quot;">​</a></h2><p>Pour ajouter un produit, cliquez sur le bouton <code>Ajouter un produit</code> sur la page : <code>/admin/commerce/products</code>.<br><img src="'+u+'" alt="Ajouter un produit"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Vous devez ajouter au moins une variante pour chaque produit. La variante contient le prix, la quantité en stock, les attributs de variation, les images, etc.</p></div>',25)]))}const x=n(c,[["render",m]]);export{P as __pageData,x as default};
